"use client"; // Obligatoire pour utiliser useEffect et fetch simplement ici
import { useEffect, useState } from "react";

export default function Home() {
  const [status, setStatus] = useState("Connexion au backend...");

  useEffect(() => {
    // On essaie d'appeler ton backend
    fetch("http://localhost:8000/auth/profile") // Remplace par une route existante du backend
      .then((res) => res.json())
      .then((data) => setStatus("Connecté au Backend ! ✅"))
      .catch((err) => setStatus("Erreur de connexion au Backend ❌"));
  }, []);

  return (
    <div className="p-8">
      <h1 className="text-2xl font-bold">Mon Dashboard IA</h1>
      <p className="mt-4 p-2 border rounded inline-block">{status}</p>
    </div>
  );
}